export const BODY: string = "\n<p>صورة AVIF منزّلة من موقع حديث غالبًا ما ترفض الفتح في التطبيق الذي تريد استخدامه. الحل تحويلها إلى JPG.</p>\n<p>الجزء الوحيد المعقد هو الشفافية، والشرط الوحيد هو متصفح حديث يستطيع فك تشفير AVIF.</p>\n<p>يأخذك هذا الدليل خطوة بخطوة، لتخرج أول تحويلة نظيفة.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: افحص متصفحك</h2>\n<p>قبل أن تبدأ، افحص متصفحك: تأكد من أن متصفحك حديث ويدعم AVIF. المتصفح القديم لا يستطيع فك تشفير AVIF.</p>\n<p>إذا كان متصفحك قديمًا، فحدّثه أولًا. التحديث مجاني ويستغرق دقائق معدودة.</p>\n<h2 id=\"step-1-open-tool\">الخطوة 1: افتح أداة AVIF إلى JPG</h2>\n<p>افتح <a href=\"/ar/tahwil-avif-ila-jpg/\">أداة AVIF إلى JPG</a> في متصفحك. تعمل الأداة بالكامل على جهازك دون رفع الصور إلى أي خادم.</p>\n<p>لا حاجة إلى حساب أو تثبيت. افتح الصفحة وابدأ فورًا، وستبقى صورك خاصة طوال العملية.</p>\n<h2 id=\"step-2-upload\">الخطوة 2: ارفع ملفات AVIF</h2>\n<p>ارفع ملفات AVIF: أسقطها في منطقة الرفع أو اخترها من جهازك. تُقبل ملفات AVIF بأي حجم معقول.</p>\n<p>إذا رفعت عدة ملفات، فستظهر كل واحدة في قائمة. يمكنك تحويلها كلها دفعة واحدة بإعدادات موحدة.</p>\n<h2 id=\"step-3-matte-colour\">الخطوة 3: اختر لون الخلفية</h2>\n<p>اختر لون الخلفية: أبيض لمعظم الحالات، وأسود للخلفيات الداكنة. اللون يملأ المناطق الشفافة في الصورة.</p>\n<p>إذا لم تكن متأكدًا، فاختر الأبيض. إنه الخيار الآمن لمعظم الوجهات، من البريد الإلكتروني إلى المواقع.</p>\n<h2 id=\"step-4-quality\">الخطوة 4: اضبط منزلق الجودة</h2>\n<p>اضبط منزلق الجودة: جودة 90 مناسبة لمعظم الصور، و85 للمشاركة اليومية. جودة 95 للصور المهمة التي تحتاج إلى أقصى حدة.</p>\n<p>لا تستخدم جودة أقل من 80 للصور فيها نصوص. النص يضبب بسرعة عند الجودة المنخفضة.</p>\n<h2 id=\"step-5-convert-preview\">الخطوة 5: حوّل وراجع النتيجة</h2>\n<p>حوّل وراجع النتيجة: اضغط زر التحويل وقارن النتيجة بالأصل. تأكد من أن الألوان صحيحة والنص حاد ولون الخلفية مناسب.</p>\n<p>إذا بدت النتيجة جيدة، فهي جاهزة. وإذا كان لون الخلفية خاطئًا، فأعد التحويل بلون مختلف.</p>\n<h2 id=\"step-6-download\">الخطوة 6: نزّل ملفات JPG</h2>\n<p>نزّل ملفات JPG: اضغط زر التنزيل واحفظ الملفات في مجلد جديد. إذا كانت عدة ملفات، فستنزّل كملف ZIP واحد.</p>\n<p>فك ضغط الملف وراجع النتائج. تحقق من أن كل ملف موجود ويبدو صحيحًا.</p>\n<ol>\n<li>ارفع ملفات AVIF.</li>\n<li>اختر لون الخلفية.</li>\n<li>اضبط الجودة.</li>\n<li>نزّل ملفات JPG.</li>\n</ol>\n<h2 id=\"converting-a-batch\">تحويل عدة تنزيلات AVIF دفعة واحدة</h2>\n<p>لتحويل عدة تنزيلات AVIF دفعة واحدة، ارفع كل الملفات وحوّلها بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP.</p>\n<p>سمِّ المجلد حسب المشروع بعد التنزيل. التنظيم الجيد يسهّل العثور على الصور لاحقًا.</p>\n<h2 id=\"fixing-problems\">كيف تحل المشاكل الشائعة؟</h2>\n<p>لحل المشاكل الشائعة، افحص السبب أولًا. الملف الذي يفشل في التحويل قد يكون تالفًا، أو متصفحك قديم لا يدعم AVIF.</p>\n<p>حدّث متصفحك أولًا، ثم أعد التحويل من الملف الأصلي. لا تعيد التحويل من النسخة المحوّلة.</p>\n<h2 id=\"after-converting\">بعد التحويل: ماذا تفعل؟</h2>\n<p>بعد التحويل، احتفظ بالملفات الأصلية AVIF كنسخة احتياطية. قد تحتاجها إذا غيّرت رأيك بشأن الجودة أو الصيغة.</p>\n<p>وللأحجام الصغيرة بعد التحويل، استخدم <a href=\"/ar/daght-as-sura-ila-100kb/\">ضاغط 100 كيلوبايت</a> أو <a href=\"/ar/daght-as-sura-ila-hajm-muayyan/\">ضاغط حجم الملف المستهدف</a>، أو حوّل إلى WebP باستخدام <a href=\"/ar/tahwil-jpg-ila-webp/\">محول JPG إلى WebP</a>.</p>\n<h2 id=\"mobile-tips\">نصائح للهواتف والأجهزة اللوحية</h2>\n<p>نصائح للهواتف والأجهزة اللوحية: افتح الأداة في المتصفح وارفع الصور من معرضك. التحويل يعمل على الهاتف دون تثبيت أي تطبيق.</p>\n<p>للدفعات الكبيرة على الهاتف، قسّمها إلى مجموعات صغيرة. المجموعات الصغيرة أسرع وأقل عرضة للفشل.</p>\n<h2 id=\"avif-for-form\">تحويل AVIF لنموذج</h2>\n<p>لتحويل AVIF لنموذج، حوّل الصورة إلى JPG بجودة عالية. النماذج تقبل JPG دائمًا، بينما ترفض AVIF غالبًا.</p>\n<p>تحقق من أبعاد الصورة المطلوبة أيضًا. بعض النماذج تطلب أبعادًا محددة بالإضافة إلى الصيغة.</p>\n<h2 id=\"avif-for-email\">تحويل AVIF لبريد إلكتروني</h2>\n<p>لتحويل AVIF لبريد إلكتروني، حوّلها إلى JPG قبل الإرسال. الملف الأصغر يرسل أسرع، وJPG يفتح في كل عميل بريد.</p>\n<p>استخدم جودة 85 للبريد الإلكتروني. الجودة كافية للعرض على الشاشة، والملف الأصغر يرسل أسرع.</p>\n<h2 id=\"avif-for-presentation\">تحويل AVIF لعرض تقديمي</h2>\n<p>لتحويل AVIF لعرض تقديمي، حوّلها إلى JPG لتقليل حجم ملف العرض. العروض الكبيرة بطيئة في الفتح والمشاركة.</p>\n<p>استخدم جودة 85 لصور العروض. الجودة كافية للشاشة الكبيرة، والملف الأصغر يجعل العرض أسرع.</p>\n<h2 id=\"avif-for-client\">تحويل AVIF لعميل</h2>\n<p>لتحويل AVIF لعميل، استخدم إعدادات موحدة وسمِّ الملفات بوضوح. أرسل ملف ZIP واحدًا مع قائمة بالمحتويات.</p>\n<p>اذكر الصيغة والإعدادات المستخدمة في رسالة التسليم. السياق الواضح يساعد العميل على استخدام الصور بشكل صحيح.</p>\n<h2 id=\"avif-on-old-computer\">تحويل AVIF على حاسوب قديم</h2>\n<p>لتحويل AVIF على حاسوب قديم، حدّث متصفحك أولًا. الحاسوب القديم قد يعمل ببطء، لكن المتصفح الحديث يستطيع فك تشفير AVIF.</p>\n<p>للدفعات الكبيرة على حاسوب قديم، قسّمها إلى مجموعات صغيرة. المجموعات الصغيرة أسرع وأقل عرضة للفشل.</p>\n<h2 id=\"avif-for-portfolio\">تحويل AVIF لمحفظة</h2>\n<p>لتحويل AVIF لمحفظة، استخدم جودة 90. المحفظة تحتاج إلى أقصى جودة، والعملاء يكبّرون الصور لفحص التفاصيل.</p>\n<p>وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-tahwil-avif-ila-jpg/\">الدليل الكامل لتحويل AVIF إلى JPG</a> و<a href=\"/ar/blog/avif-vs-jpg/\">AVIF مقابل JPG</a>، أو جرّب <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a> لصيغ أخرى.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أحوّل عدة تنزيلات AVIF دفعة واحدة؟","answer":"ارفع كل ملفات AVIF دفعة واحدة وحوّلها بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP واحد."},{"question":"ماذا أفعل إذا لم يستطع متصفحي فك تشفير ملف AVIF؟","answer":"حدّث متصفحك إلى أحدث إصدار. إذا استمرت المشكلة، فجرّب متصفحًا آخر مثل كروم أو فايرفوكس الحديث."},{"question":"ما نسبة الجودة الأنسب لصور AVIF؟","answer":"جودة 90 مناسبة لمعظم صور AVIF: التفاصيل تبقى واضحة والملف أصغر بكثير. للصور المهمة استخدم 95."},{"question":"هل يمكنني مراجعة ملف JPG المحوّل قبل تنزيله؟","answer":"نعم، قارن النتيجة بالأصل قبل التنزيل. تأكد من أن الألوان صحيحة والنص حاد ولون الخلفية مناسب."},{"question":"هل يعمل تحويل AVIF إلى JPG في متصفحات الهواتف؟","answer":"نعم، التحويل يعمل في متصفحات الهواتف الحديثة دون تثبيت أي تطبيق. افتح الأداة وارفع الصورة وحوّلها ونزّل النتيجة."},{"question":"متى أحوّل AVIF إلى JPG بدل AVIF إلى PNG؟","answer":"اختر JPG عندما تحتاج إلى توافق كامل مع الأنظمة القديمة، وPNG عندما تحتاج إلى شفافية أو تحرير متكرر."}];
